import { sumAmounts } from "./sum-amounts";
import { formatAmount, type MemberDetails } from "./entity-details";

export interface MemberMoneySource {
  funder: MemberDetails["declarations"][number]["entries"][number]["funder"];
  amount: string | null;
  entryCount: number;
  missingGbpAmountCount: number;
  unknownCurrencyCount: number;
  foreignCurrencyCount: number;
}

function compareAmounts(left: string | null, right: string | null): number {
  if (left === null) return right === null ? 0 : 1;
  if (right === null) return -1;
  const difference = sumAmounts([
    right,
    left.startsWith("-") ? left.slice(1) : `-${left}`,
  ]);
  if (difference === null || /^-?0(?:\.0+)?$/u.test(difference)) return 0;
  return difference.startsWith("-") ? -1 : 1;
}

function moneySources(details: MemberDetails): MemberMoneySource[] {
  const groups = new Map<
    string | null,
    { source: MemberMoneySource; amounts: string[] }
  >();
  for (const declaration of details.declarations) {
    for (const entry of declaration.entries) {
      const key = entry.funder?.id ?? null;
      let group = groups.get(key);
      if (!group) {
        group = {
          source: {
            funder: entry.funder,
            amount: null,
            entryCount: 0,
            missingGbpAmountCount: 0,
            unknownCurrencyCount: 0,
            foreignCurrencyCount: 0,
          },
          amounts: [],
        };
        groups.set(key, group);
      }
      group.source.entryCount += 1;
      if (entry.currency === "GBP") {
        if (entry.amount === null) group.source.missingGbpAmountCount += 1;
        else group.amounts.push(entry.amount);
      } else if (!entry.currency?.trim())
        group.source.unknownCurrencyCount += 1;
      else group.source.foreignCurrencyCount += 1;
    }
  }
  return Array.from(groups.values(), ({ source, amounts }) => ({
    ...source,
    amount: sumAmounts(amounts),
  })).sort(
    (left, right) =>
      compareAmounts(left.amount, right.amount) ||
      (left.funder?.name ?? "Source unavailable").localeCompare(
        right.funder?.name ?? "Source unavailable",
        "en",
      ) ||
      (left.funder?.id ?? "").localeCompare(right.funder?.id ?? ""),
  );
}

export function formatPounds(amount: string | null): string {
  if (amount === null) return formatAmount(null);
  const unsigned = amount.replace(/^-/, "");
  const [whole, fraction = ""] = unsigned.split(".");
  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
}

export function summarizeMember(details: MemberDetails) {
  const pounds = details.summary.currencies.find(
    (group) => group.currency === "GBP",
  );
  return {
    total: pounds?.amount ?? null,
    firstRegisteredAt: details.summary.firstRegisteredAt,
    declaredTotals: details.summary.declaredTotals,
    categories: pounds?.categories ?? [],
    sources: moneySources(details),
  };
}
import type { FunderDetails } from "./entity-details";

const colors = [
  "#df8550",
  "#6587ad",
  "#b39e53",
  "#809c79",
  "#9a83b5",
  "#bf747c",
];

const partyColors = new Map<string, string>([
  ["Labour", "#e4003b"],
  ["Conservative", "#0087dc"],
  ["Reform UK", "#8b5cf6"],
  ["Liberal Democrat", "#ffe500"],
  ["Green Party", "#00a85a"],
  ["Scottish National Party", "#c7a600"],
]);

type Party = FunderDetails["currencies"][number]["parties"][number];

function scaledAmount(amount: string | null, scale: number): bigint | null {
  if (amount === null) return null;
  const [whole, fraction = ""] = amount.split(".");
  return BigInt(whole + fraction.padEnd(scale, "0"));
}

function decimalAmount(value: bigint, scale: number): string {
  const digits = (value < 0n ? -value : value)
    .toString()
    .padStart(scale + 1, "0");
  const amount =
    scale === 0
      ? digits
      : `${digits.slice(0, -scale)}.${digits.slice(-scale)}`.replace(
          /\.?0+$/u,
          "",
        );
  return `${value < 0n ? "-" : ""}${amount}`;
}

export function partyChart(
  parties: FunderDetails["currencies"][number]["parties"],
) {
  const scale = Math.max(
    0,
    ...parties.map((party) => party.amount?.split(".")[1]?.length ?? 0),
  );
  const grouped: Party[] = [];
  let labour: { party: Party; amount: bigint | null } | undefined;
  for (const party of parties) {
    if (party.partyName !== "Labour" && party.partyName !== "Labour (Co-op)") {
      grouped.push(party);
      continue;
    }
    const amount = scaledAmount(party.amount, scale);
    if (labour === undefined) {
      labour = { party: { ...party, partyName: "Labour" }, amount };
      grouped.push(labour.party);
    } else {
      if (amount !== null) labour.amount = (labour.amount ?? 0n) + amount;
      labour.party.entryCount += party.entryCount;
      labour.party.unknownAmountCount += party.unknownAmountCount;
    }
  }
  if (labour !== undefined) {
    labour.party.amount =
      labour.amount === null ? null : decimalAmount(labour.amount, scale);
  }
  const values = grouped.map(({ amount }) => {
    const value = scaledAmount(amount, scale) ?? 0n;
    return value > 0n ? value : 0n;
  });
  const total = values.reduce((sum, value) => sum + value, 0n);
  let start = 0;
  return grouped.map((party, index) => {
    const share =
      total === 0n ? 0 : Number((values[index] * 1000000n) / total) / 1000000;
    const angle = share * Math.PI * 2;
    const end = start + angle;
    const path =
      share === 0 || share === 1
        ? ""
        : `M 100 100 L ${100 + 90 * Math.sin(start)} ${100 - 90 * Math.cos(start)} A 90 90 0 ${share > 0.5 ? 1 : 0} 1 ${100 + 90 * Math.sin(end)} ${100 - 90 * Math.cos(end)} Z`;
    start = end;
    return {
