/tmp/period-baseline-check.mjs.content:
import assert from 'node:assert/strict';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
const [mode, origin, evidence] = process.argv.slice(2);
assert(['feature', 'baseline'].includes(mode));
await mkdir(evidence, { recursive: true });
async function get(path) {
  const response = await fetch(origin + path);
  assert.equal(response.status, 200, path);
  return response.json();
}
if (mode === 'feature') {
  const paths = ['/members/178?period=historical', '/members/4613?period=historical'];
  for (const [term, name] of [['bbc', 'BBC'], ['gb news', 'GB News'], ['premier league', 'Premier League']]) {
    const result = await get(`/search?term=${encodeURIComponent(term)}&max_entries=10&strictness=0.8`);
    const matches = result.entities.filter(entity => entity.name === name && entity.kind === 'Funder');
    assert.equal(matches.length, 1);
    paths.push(`/funders/${matches[0].id}?period=historical`);
  }
  paths.push('/rankings?period=current-term');
  const observations = [];
  for (const path of paths) observations.push({ path, body: await get(path) });
  await writeFile(`${evidence}/feature.json`, JSON.stringify(observations, null, 2));
  console.log(`Captured ${observations.length} feature API responses from the preview snapshot.`);
} else {
  const observations = JSON.parse(await readFile(`${evidence}/feature.json`, 'utf8'));
  const baseline = [];
  for (const { path, body } of observations) {
    const expected = await get(path);
    const { period, ...projection } = body;
    assert.deepEqual(projection, expected, path);
    baseline.push({ path, body: expected });
  }
  await writeFile(`${evidence}/main.json`, JSON.stringify(baseline, null, 2));
  console.log(`All ${baseline.length} responses exactly match main on the same snapshot after excluding the new period field. This includes all three production-differing funders, both member detail responses, and current-term rankings.`);
}

