import {writeFile} from 'node:fs/promises';
const browser=await chromium.launch();
const result=[];
try {
 const page=await browser.newPage({viewport:{width:1440,height:1000},reducedMotion:'reduce'});
 for(const path of ['/rankings','/members/4462','/funders/01a1212e-2078-75fe-bcdf-052757de49ca']) {
  const response=await page.goto('http://localhost:4179'+path,{waitUntil:'networkidle'});
  assert.equal(response.status(),200);
  const navigation=page.getByRole('navigation',{name:'Reporting period'});
