   await navigation.locator('[aria-current=page]').filter({hasText:label}).waitFor();
   assert.equal(new URL(page.url()).searchParams.get('period'),period);
   assert.equal(await page.getByRole('alert').count(),0);
   result.push({path,period,url:page.url(),headline:await page.locator('.declared-totals').innerText().catch(()=>null)});
  }
 }
 await page.getByRole('link',{name:'Funding history',exact:true}).click();
