test("member summary retains signed category bars alongside all-category totals", async ({
  backend,
  page,
  context,
}) => {
  await mockDetails(backend);
  await page.goto("/members/1");
  await expect(page.locator(".member-total")).toHaveText(["£24,691.34"]);
  await expect(page.locator(".signed-bar .negative")).toHaveCount(1);
  await expect(
    page
      .locator(".category-label")
      .filter({ hasText: "Unrecognized source category" }),
  ).toContainText("−£5.00");
  await expect(
    page.locator(
      ".member-currency-totals, .member-overview, .category-currency",
    ),
  ).toHaveCount(0);
  await expect(page.locator(".member-identity")).toContainText(
    "Declared amounts",
  );
  const total = await page.locator(".member-total").first().boundingBox();
  const tabs = await page.locator(".member-tabs").boundingBox();
  expect(total && tabs && total.y + total.height <= tabs.y).toBeTruthy();
  await expect(page.locator(".declarations-list")).toHaveCount(0);
  await expect(
    page.getByRole("link", { name: "Declaration history", exact: true }),
  ).toHaveAttribute("href", "/members/1/history?period=current-term");
});

test("history filters the full dataset before paging and resets page for date changes", async ({
  backend,
  },
  { name: "zero", amount: "0", count: 1, incomplete: true, expected: "£0.00" },
] as const) {
  for (const kind of ["member", "funder"] as const) {
    test(`${kind} selected headline preserves ${state.name} independently of populated other periods`, async ({
      page,
      backend,
    }) => {
      const path = kind === "member" ? "/members/1" : `/funders/${funderId}`;
      const total = declaredTotals(
        { amount: "1", declaration_count: 1, incomplete: false },
        { amount: "200", declaration_count: 2, incomplete: false },
        {
          amount: state.amount,
          declaration_count: state.count,
          incomplete: state.incomplete,
        },
      );
      await backend.route(`**/api${path}?*`, (route) =>
        route.fulfill({
          json:
            kind === "member"
              ? {
                  ...memberDetails,
                  period: "current-year",
                  summary: { ...memberDetails.summary, declared_totals: total },
                }
              : {
                  ...funderDetails,
                  period: "current-year",
                  declared_totals: total,
                },
        }),
      );
      await page.goto(`${path}?period=current-year`);
      await expect(page.locator(".declared-totals .member-total")).toHaveText([
        state.expected,
      ]);
      if (state.amount !== null)
        await expect(
          page.locator(".declared-totals [role=region]"),
        ).toHaveAttribute(
          "title",
          "Known GBP amounts only. Some amounts unavailable.",
        );
      else
        await expect(
          page.locator(".declared-totals [role=region]"),
        ).toHaveCount(0);
    });
  }
}

