  import { Metric } from "./lib/ui";
  import { formatPounds } from "./lib/member-summary";
  import type { DeclaredGbpTotals } from "./lib/entity-details";
  import { declaredTotal, type ReportingPeriod } from "./lib/reporting-period";
  let {
    totals,
    period,
  }: { totals: DeclaredGbpTotals; period: ReportingPeriod } = $props();
  const total = $derived(declaredTotal(totals, period));
</script>

<div class="declared-totals">
  <Metric
    variant="expanded"
    label="Declared amounts"
    regionLabel="Declared amounts in GBP"
    value={total.declarationCount === 0
      ? "No declarations recorded"
      : formatPounds(total.amount)}
    available={total.declarationCount > 0 && total.amount !== null}
    description={total.incomplete
      ? "Known GBP amounts only. Some amounts unavailable."
      : undefined}
  />
</div>
<script lang="ts">
  let {
    variant = "default",
    align,
    label,
    regionLabel = label,
    value,
    available = true,
    description,
    level = 2,
  }: {
    variant?: "default" | "expanded";
    align?: "start" | "end";
    label: string;
    regionLabel?: string;
    value: string;
    available?: boolean;
    description?: string;
    level?: 2 | 3;
  } = $props();
</script>

<div class="member-value" data-variant={variant} data-align={align}>
  <svelte:element this={`h${level}`} class="ui-metric-label"
    >{label}</svelte:element
  >
  {#if available}<!-- svelte-ignore a11y_no_noninteractive_tabindex (Exact amounts must be keyboard scrollable.) -->
    <div
      class="member-total"
      role="region"
      tabindex="0"
      aria-label={regionLabel}
      title={description}
    >
      {value}
    </div>{:else}<p class="member-total unavailable">{value}</p>{/if}
</div>
<script lang="ts">
  import type { SignedBar } from "./chart-types";
  let {
    bars,
    baseline,
    variant = "default",
  }: {
    bars: SignedBar[];
    baseline: number;
    variant?: "default" | "compact";
  } = $props();
</script>

<ul
  class="category-list"
  data-variant={variant}
  style:--baseline={`${baseline}%`}
>
  {#each bars as bar}<li>
      <div class="category-label">
        <span>{bar.label}</span><span class="amount">{bar.value}</span>
      </div>
      <div class="signed-bar" aria-hidden="true">
        <span class:negative={bar.negative} style:width={`${bar.width}%`}
        ></span>
      </div>
      {#if bar.note}<p class="partial-note">{bar.note}</p>{/if}
    </li>{/each}
</ul>
<script lang="ts">
  import type { RankingRow } from "./ranking-types";
  let { rows, label }: { rows: RankingRow[]; label: string } = $props();
</script>

<ol class="ranking-list" role="list" aria-label={label}>
  {#each rows as row, index (row.key)}
    <li data-accent={row.accent} style:--row-delay={`${index * 35}ms`}>
      <span class="rank" aria-hidden="true">{index + 1}</span>
      <div class="identity">
        {#if row.href}<a href={row.href}>{row.name}</a>{:else}<span class="name"
