          >{/if}
        <span class="context">{row.context}</span>
      </div>
      <span class="bar-track" aria-hidden="true"
        ><span class:negative={row.negative} style:width={`${row.width}%`}
        ></span></span
      >
      <span class="value">{row.amount}</span>
      {#if row.incomplete}<span class="incomplete">Incomplete</span>{/if}
    </li>
  {/each}
</ol>

<style>
  .ranking-list {
    padding: 0;
    margin: 0;
    list-style: none;
  }
  li {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr) fit-content(50%);
    align-items: start;
    column-gap: var(--space-3);
    row-gap: var(--space-1);
    padding: var(--space-2) 0;
    border-bottom: 1px solid var(--line);
    animation: ranking-enter 300ms both;
    animation-delay: var(--row-delay);
  }
  [data-accent="member"] {
    --row-accent: var(--accent-member);
  }
  [data-accent="funder"] {
    --row-accent: var(--accent-funder);
  }
  [data-accent="neutral"] {
    --row-accent: var(--muted);
  }
  .rank {
    color: var(--muted);
    font-size: var(--text-small);
    padding-top: 2px;
    font-variant-numeric: tabular-nums;
  }
  .identity {
    grid-column: 2 / -1;
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    min-width: 0;
  }
  a,
  .name {
    color: var(--text);
    font-size: var(--text-body);
    font-weight: 600;
    overflow-wrap: anywhere;
    text-decoration: none;
  }
  a:hover {
    text-decoration: underline;
  }
  .context,
  .incomplete {
    color: var(--muted);
    font-size: var(--text-small);
  }
  .bar-track {
    grid-column: 2;
    grid-row: 2;
    align-self: center;
    display: block;
    height: 3px;
    background: var(--surface);
  }
  .bar-track > span {
    display: block;
    height: 100%;
    background: var(--row-accent);
    transform-origin: left;
    animation: ranking-bar 420ms both;
    animation-delay: var(--row-delay);
  }
  .bar-track > span.negative {
    opacity: 0.5;
  }
  .value {
    grid-column: 3;
    grid-row: 2;
    color: var(--row-accent);
    min-width: 0;
    max-width: 330px;
    text-align: right;
    font-size: var(--text-heading);
    font-variant-numeric: tabular-nums;
    overflow-wrap: anywhere;
  }
  .incomplete {
    grid-column: 3;
    grid-row: 3;
    text-align: right;
  }
  @keyframes ranking-enter {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
