type MotionPreset = "roll-up" | "row" | "bar" | "fade";

type EntryMotionOptions = {
  preset: MotionPreset;
  changeKey?: string;
  initial?: boolean;
  index?: number;
};

const presets = {
  "roll-up": {
    frames: [{ transform: "translateY(100%)" }, { transform: "translateY(0)" }],
    duration: 200,
    easing: "ease-out",
  },
  row: {
    frames: [{ opacity: 0, transform: "translateY(8px)" }, { opacity: 1, transform: "translateY(0)" }],
    duration: 300,
    easing: "ease",
  },
  bar: {
    frames: [{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }],
    duration: 420,
    easing: "ease",
  },
  fade: {
    frames: [{ opacity: 0.65 }, { opacity: 1 }],
    duration: 200,
    easing: "ease-out",
  },
} satisfies Record<MotionPreset, { frames: Keyframe[]; duration: number; easing: string }>;

export function entryMotion(node: HTMLElement, options: EntryMotionOptions) {
  const preference = matchMedia("(prefers-reduced-motion: reduce)");
  let previousKey = options.changeKey;
  let animation: Animation | undefined;

  function play(next: EntryMotionOptions) {
    animation?.cancel();
    if (preference.matches) return;
    const preset = presets[next.preset];
    animation = node.animate(preset.frames, {
      duration: preset.duration,
      easing: preset.easing,
      delay: (next.index ?? 0) * 35,
      fill: "backwards",
    });
  }

  function cancelReducedMotion() {
    if (preference.matches) animation?.cancel();
  }
  preference.addEventListener("change", cancelReducedMotion);
  if (options.initial) play(options);

  return {
    update(next: EntryMotionOptions) {
      if (next.changeKey === previousKey) return;
      previousKey = next.changeKey;
      play(next);
    },
    destroy() {
      preference.removeEventListener("change", cancelReducedMotion);
      animation?.cancel();
    },
  };
}
<script lang="ts">
  import { entryMotion } from "./entry-motion";
  let {
    variant = "default",
    align,
    label,
    regionLabel = label,
    value,
    available = true,
    description,
    level = 2,
    changeKey,
  }: {
    variant?: "default" | "expanded";
    align?: "start" | "end";
    label: string;
    regionLabel?: string;
    value: string;
    available?: boolean;
    description?: string;
    level?: 2 | 3;
    changeKey?: string;
  } = $props();
</script>

<div class="member-value" data-variant={variant} data-align={align}>
  <svelte:element this={`h${level}`} class="ui-metric-label"
    >{label}</svelte:element
  >
  {#if available}<!-- svelte-ignore a11y_no_noninteractive_tabindex (Exact amounts must be keyboard scrollable.) -->
    <div
      class="member-total"
      role="region"
      tabindex="0"
      aria-label={regionLabel}
      title={description}
    >
      <span class="metric-value-clip"><span class="metric-value" use:entryMotion={{ preset: "roll-up", changeKey }}>{value}</span></span>
    </div>{:else}<p class="member-total unavailable">{value}</p>{/if}
</div>
<script lang="ts">
